import{_ as s,l as n,o as a,c as d,v as o,p as i,x as t,d as l,i as c,S as E}from"./chunks/framework.InCnrqk-.js";const C=JSON.parse('{"title":"大小端","description":"","frontmatter":{"title":"大小端","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/endianness.md","filePath":"cs/endianness.md","lastUpdated":1789023840000}'),p={name:"cs/endianness.md"};function A(h,e,B,S,_,m){const r=n("Mermaid");return a(),d("div",null,[e[1]||(e[1]=o('<h1 id="大小端" tabindex="-1">大小端 <a class="header-anchor" href="#大小端" aria-label="Permalink to &quot;大小端&quot;">​</a></h1><div class="epigraph"><p>多字节整数在内存里从哪一端放下「最低位字节」，是 ISA 与协议必须钉死的约定；算术在寄存器里并不知道自己曾被拆成哪一串字节。</p><footer>—— 据 Cohen, On Holy Wars and a Plea for Peace, IEEE Computer 1981；The RISC-V Instruction Set Manual；ARM ARM；Intel SDM 整理</footer></div><p><a href="/cs/condition-codes-predication">上一课</a>决定比较结果放标志还是放 GPR。寄存器内部的位编号与<strong>内存字节序</strong>不是同一件事。缺口是 <strong>endianness</strong>：x86/RISC-V 默认小端，网络与部分历史 ISA 大端，ARM 可双端。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p><code>sw</code> 把 32 位值写成四个字节。小端：最低地址放最低有效字节；大端相反。CPU 在 GPR 里做的加、<a href="/cs/bit-manip-ext">位操作</a> 的 <code>rev8</code> 正是在两种视图之间翻。缺口不是再讲 load/store，而是<strong>同一比特串在总线与文件里的排列</strong>，以及跨核、跨设备、跨网络时必须一致。</p><p>指令流：RISC-V/A64 取指也按约定的端序读半字/字；与数据端序通常相同，但规范允许实现另述。把「位 0 是 LSB」直接当成「地址 0 是 LSB 字节」，对照课会混。</p><h3 id="大小端不是「谁更自然」" tabindex="-1">大小端不是「谁更自然」 <a class="header-anchor" href="#大小端不是「谁更自然」" aria-label="Permalink to &quot;大小端不是「谁更自然」&quot;">​</a></h3><p>Cohen 1981 已经指出争论多半是命名。本课不选边。也不把 TCP 的 network byte order 写成要在本栏实现的协议栈——只要求：多字节字段在共享内存与 ABI 里有端序。</p><p><span class="marginnote">Cohen, IEEE Computer 1981。Intel 长期小端（SDM）。ARM ARM 的字节序与 <code>SETEND</code> 历史、A64 默认 LE。RISC-V 非特权默认小端；特权规范可提供端序控制位。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>编译器按目标 ABI 生成字访问；跨端数据用显式字节交换（<code>rev</code>/<code>bswap</code>/<code>rev8</code>）或按字节读写。原子与 <a href="/cs/lr-sc-cas">LR/SC</a> 的对象是整字，端序决定那一颗字的内存图像，不改变保留集语义。<a href="/cs/simd-extensions">SIMD</a> 的打包通道有自己的元素序，和标量端序一起写进手册，不要靠猜测。</p>',11)),(a(),i(E,null,{default:t(()=>[c(r,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20REG%5B%22GPR%20%E4%B8%AD%E7%9A%84%E6%95%B4%E6%95%B0%22%5D%20--%3E%20ST%5B%22store%20%E6%8B%86%E5%AD%97%E8%8A%82%22%5D%0A%20%20ST%20--%3E%20LE%5B%22%E5%B0%8F%E7%AB%AF%EF%BC%9A%E4%BD%8E%E5%9C%B0%E5%9D%80%3DLSB%22%5D%0A%20%20ST%20--%3E%20BE%5B%22%E5%A4%A7%E7%AB%AF%EF%BC%9A%E4%BD%8E%E5%9C%B0%E5%9D%80%3DMSB%22%5D%0A%20%20LE%20--%3E%20LATER%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9A%E8%BF%99%E4%BA%9B%E5%AD%97%E8%8A%82%E8%BF%98%E8%A6%81%E5%AF%B9%E9%BD%90%22%5D%0A%20%20BE%20--%3E%20LATER%0A"})]),fallback:t(()=>[...e[0]||(e[0]=[l(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=o('<p>与页表：PTE 多字节字段同样有端序；<a href="/cs/sv39-page-table">Sv39</a> 在小端内存上定义位域。hypervisor 填 <code>hgatp</code> 指向的表时不能按大端主机格式瞎写。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>条件码不编码端序。下一课对齐：即使端序已知，地址相对宽度未对齐时，一次「逻辑上的字访问」可能拆成两次总线事务，或直接 trap。ISA 对照必须把「允不允许非对齐」与「端序」分开写。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不裁定文件格式，不把 base64 当端序。不保证所有 RISC-V 核实现大端模式。不进入量化行情的 wire 格式。</p><p>后课默认：当代 x86 与默认 RISC-V/A64 用户态是小端；跨端要显式交换。下一课对齐与非对齐访问。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>端序规定多字节在内存中的字节排列。</li><li>寄存器算术不自动知道磁盘与网络的端序。</li><li><code>bswap</code>/<code>rev8</code> 是 ISA 提供的翻转。</li><li>出处：Cohen 1981；RISC-V ISA；ARM ARM；Intel SDM。</li></ul>',8))])}const f=s(p,[["render",A]]);export{C as __pageData,f as default};
